import java.util.*;
class K {
  String n;
  K(String n) { this.n = n; }
  public boolean equals(Object o) { return o instanceof K k && k.n.equals(n); }
}
class Main {
  public static void main(String[] args) {
    Set<K> s = new HashSet<>();
    s.add(new K("a"));
    System.out.println(s.contains(new K("a")));
  }
}

